package com.bananalab.lite;
import java.util.*;
final class SourceLex{
 static final class Span{final int a,b;final char kind;Span(int a,int b,char k){this.a=a;this.b=b;kind=k;}}
 static List<Span> spans(String s){List<Span> out=new ArrayList<>();for(int i=0;i<s.length();){int a=i;char c=s.charAt(i),n=i+1<s.length()?s.charAt(i+1):0;if(c=='/'&&n=='/'){i+=2;while(i<s.length()&&s.charAt(i)!='\n')i++;out.add(new Span(a,i,'c'));}else if(c=='/'&&n=='*'){int end=s.indexOf("*/",i+2);if(end<0)throw new IllegalArgumentException("Comentario sin cerrar");i=end+2;out.add(new Span(a,i,'c'));}else if(c=='"'||c=='\''){if(s.startsWith("\"\"\"",i))throw new IllegalArgumentException("Editor compatible con Java8, sin bloques de texto");boolean done=false;i++;while(i<s.length()){char q=s.charAt(i++);if(q=='\\'){if(i<s.length())i++;}else if(q==c){done=true;break;}}if(!done)throw new IllegalArgumentException("Literal sin cerrar");out.add(new Span(a,i,c));}else i++;}return out;}
 static String masked(String s){char[] chars=s.toCharArray();for(Span p:spans(s))for(int i=p.a;i<p.b;i++)if(chars[i]!='\n'&&chars[i]!='\r')chars[i]=' ';return new String(chars);}
 static boolean unicode(String s){for(int i=0;i<s.length();i++)if(s.charAt(i)=='\\'){int a=i;while(i<s.length()&&s.charAt(i)=='\\')i++;if((i-a)%2==1&&i<s.length()&&s.charAt(i)=='u')return true;i--;}return false;}
 static String decode(String raw)throws Exception{return new org.json.JSONArray("["+raw+"]").getString(0);}
 static String quote(String s){return "\""+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t").replace("\b","\\b").replace("\f","\\f")+"\"";}
 static String literal(String s,String from,String to)throws Exception{StringBuilder out=new StringBuilder();int at=0;for(Span p:spans(s))if(p.kind=='"'&&decode(s.substring(p.a,p.b)).equals(from)){out.append(s,at,p.a).append(quote(to));at=p.b;}return out.append(s.substring(at)).toString();}
 static String rename(String s,String from,String to)throws Exception{if(!s.contains(from))return s;if(unicode(s))throw new IllegalArgumentException("Renombración ambigua con escapes Unicode; editá explícitamente el archivo");for(Span p:spans(s))if(p.kind=='"'&&decode(s.substring(p.a,p.b)).equals(from))throw new IllegalArgumentException("Ese identificador también aparece como texto; podría usarse en reflexión o datos");String code=masked(s);StringBuilder out=new StringBuilder();int at=0;for(int i=0;i<code.length();){if(Character.isJavaIdentifierStart(code.charAt(i))){int a=i++;while(i<code.length()&&Character.isJavaIdentifierPart(code.charAt(i)))i++;if(code.substring(a,i).equals(from)){out.append(s,at,a).append(to);at=i;}}else i++;}return out.append(s.substring(at)).toString();}
}
